CREATE TABLE supplier_invoice_lines (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,supplier_invoice_id BIGINT UNSIGNED NOT NULL,description VARCHAR(500) NOT NULL,cost_code_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(18,2) NOT NULL,sort_order INT UNSIGNED NOT NULL,work_section_code_snapshot VARCHAR(20) NULL,work_section_name_snapshot VARCHAR(190) NULL,cost_code_snapshot VARCHAR(30) NULL,cost_code_name_snapshot VARCHAR(255) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_supplier_invoice_lines_order(supplier_invoice_id,sort_order,id),KEY idx_supplier_invoice_lines_cost_code(cost_code_id),CONSTRAINT fk_supplier_invoice_lines_invoice FOREIGN KEY(supplier_invoice_id) REFERENCES supplier_invoices(id) ON DELETE RESTRICT,CONSTRAINT fk_supplier_invoice_lines_cost_code FOREIGN KEY(cost_code_id) REFERENCES cost_codes(id) ON DELETE RESTRICT,CONSTRAINT chk_supplier_invoice_lines_amount CHECK(amount>0),CONSTRAINT chk_supplier_invoice_lines_sort CHECK(sort_order>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
